import pandas as pd

def clean(df):
    date_errors = []
    for idx, row in df.iterrows():
        date_str = row['Date']
        try:
            dt = pd.to_datetime(date_str, format='%Y-%m-%d')
            if date_str.lower() in ['tbd', 'not-a-date']:
                raise ValueError
            # Keep valid datetime
        except:
            date_errors.append(idx)
    df = df.drop(index=date_errors)

    price_errors = []
    for idx, row in df.iterrows():
        price_str = row['Price']
        try:
            price = float(price_str)
        except:
            price_errors.append(idx)
            continue
    df = df.drop(index=price_errors)

    quantity_out = []
    for idx, row in df.iterrows():
        q = row['Quantity']
        if not (1 <= q <= 8):
            quantity_out.append(idx)
    df = df.drop(index=quantity_out)

    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    category_out = []
    for idx, row in df.iterrows():
        cat = row['Category']
        if cat not in allowed:
            category_out.append(idx)
    df = df.drop(index=category_out)

    df['Revenue'] = df.apply(lambda x: x['Quantity'] * x['Price'], axis=1)
    rev_out = []
    for idx, row in df.iterrows():
        rev = row['Revenue']
        if not (12 <= rev <= 3600):
            rev_out.append(idx)
    df = df.drop(index=rev_out)

    return df

def answer(df):
    df['month'] = df['Date'].dt.strftime('%Y-%m')
    monthly = df.groupby('month')['Revenue'].sum().reset_index()
    total = monthly['Revenue'].sum()
    monthly['all'] = total
    result = {}
    for row in monthly.itertuples():
        result[row.month] = row.Revenue
    result['all'] = total
    return result
